'use strict';
let DATA;
const state={view:'overview',brand:'All brands',query:'',sort:'curated',page:1,method:0,archiveQuery:'',archiveType:'All files',insightBrand:'All watchmakers',segment:'All segments',movement:'All movements',watchKind:'All watch types',gems:false,spotlight:0,motionPaused:false};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-US');
const safeUrl=u=>{try{const x=new URL(u);return x.protocol==='https:'?x.href:''}catch{return ''}};
const price=r=>r.price_value!==null&&r.price_value!==undefined?`${r.currency||''} ${fmt(r.price_value)}`:r.price||(r.source_kind==='Official catalog'?'Price not published':'Price not captured');
const friendly=k=>k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()).replace('Url','URL');
const stepNames=['Research','Plan','Scrape','Prepare','Present'];
const stepSummary=['Discover collections & product templates','Pilot the extraction & define the schema','Navigate pages & capture specifications','Join, review & standardize datasets','Build an explorable research catalog'];
const featured=()=>(DATA.showcaseBrands||['Audemars Piguet','H. Moser & Cie.','Bulgari']).map(b=>DATA.records.find(r=>r.brand===b&&r.image_url));
const visual=r=>`<div class="watch-visual"><div class="fallback"><strong>${esc(r.brand)}</strong><small>${esc(r.reference_number||'WATCH ATLAS')}</small></div>${safeUrl(r.image_url)?`<img src="${esc(safeUrl(r.image_url))}" alt="${esc(r.brand+' '+r.specific_model)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()" onload="this.parentElement.querySelector('.fallback').hidden=true">`:''}</div>`;
const watchCard=r=>`<button class="watch-card" data-record="${r.id}" aria-label="View ${esc(r.brand+' '+r.specific_model+' '+r.reference_number)}">${visual(r)}<div class="watch-body"><div class="watch-brand">${esc(r.brand)}</div><h3 class="watch-name">${esc(r.specific_model)}</h3><p class="watch-ref">${esc(r.reference_number)}</p><span class="watch-tag segment">${esc(r.segment)}</span>${r.watch_kind==='Pocket watch'?'<span class="watch-tag">Pocket watch</span>':''}${r.gem_set?'<span class="watch-tag gem">Gem details</span>':''}<div class="watch-bottom"><span>${esc(r.diameter_mm!==null?r.diameter_mm+' mm':r.diameter||'Case size unspecified')}</span><span>${esc(r.movement_family==='Not specified'?'Movement unspecified':r.movement_family)}</span></div></div></button>`;
const viewIntro=(eyebrow,title,description)=>`<div class="view-intro"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div>`;
function overview(){
const a=DATA.insights.overall;const largest=[...DATA.insights.segments].filter(x=>x.diameterAvg!==null).sort((a,b)=>b.diameterAvg-a.diameterAvg)[0];const gemLeader=[...DATA.insights.brands].sort((a,b)=>b.gemPercent-a.gemPercent)[0];
return `<section class="atlas-hero"><div class="hero-copy"><p class="eyebrow">THE WATCH ATLAS / VOLUME 01</p><h1>Every watch.<br><em>A different story.</em></h1><p>Explore ${fmt(a.count)} references across ${DATA.insights.brands.length} watchmakers. Discover the collections, dimensions and details that set them apart.</p><div class="hero-actions"><button class="button primary" data-view="catalog">Explore the watches</button><button class="button quiet" data-view="insights">Discover the insights</button></div><div class="hero-caption"><span class="hairline"></span>${DATA.insights.brands.length} watchmakers. Countless expressions of time.</div></div><div class="watch-stage" id="watch-stage"><div class="stage-grid" aria-hidden="true"></div><div class="stage-orbit" aria-hidden="true"></div><button class="motion-toggle" id="motion-toggle" aria-pressed="${state.motionPaused}" aria-label="${state.motionPaused?'Resume':'Pause'} watch animation">${state.motionPaused?'Play animation':'Pause animation'}</button><div id="spotlight-watch"></div><div class="stage-controls" id="stage-controls"></div></div></section>
<section class="metrics customer-metrics" aria-label="Collection highlights"><div class="metric"><span class="metric-title">Watch references</span><span class="metric-value">${fmt(a.count)}</span><span class="metric-note">Across the collection</span></div><div class="metric"><span class="metric-title">Watchmakers</span><span class="metric-value">${String(DATA.insights.brands.length).padStart(2,'0')}</span><span class="metric-note">Distinct approaches to watchmaking</span></div><div class="metric"><span class="metric-title">Average case diameter</span><span class="metric-value">${a.diameterAvg.toFixed(1)}<small> mm</small></span><span class="metric-note">${fmt(a.diameterN)} wristwatch diameters measured</span></div><div class="metric"><span class="metric-title">Distinct calibers</span><span class="metric-value">${a.calibers}</span><span class="metric-note">Movement designs in the collection</span></div></section>
<section class="discovery-section"><div class="section-heading"><div><p class="eyebrow">A CLOSER LOOK</p><h2>Three remarkable expressions.</h2></div><button class="text-button" data-view="catalog">View the collection</button></div><div class="featured-grid">${featured().map(watchCard).join('')}</div></section>
<section class="preview-insights"><div class="section-heading"><div><p class="eyebrow">BEYOND THE DIAL</p><h2>Patterns worth discovering.</h2></div><button class="text-button" data-view="insights">Explore all insights</button></div><div class="insight-preview-grid"><button class="insight-preview" data-view="insights"><span class="tiny-label">CASE SIZE</span><h3>Built for a bigger presence.</h3><div class="preview-number">${largest.diameterAvg.toFixed(1)} <small>mm</small></div><p>${esc(largest.name)} watches have the largest average diameter in this collection.</p><span class="preview-link">Compare the segments</span></button><button class="insight-preview" data-view="insights"><span class="tiny-label">PRECIOUS DETAILS</span><h3>A jeweller’s signature.</h3><div class="preview-number">${gemLeader.gemPercent.toFixed(1)}<small>%</small></div><p>Of ${esc(gemLeader.name)} references mention decorative gemstones—the highest share here.</p><span class="preview-link">Explore gemstone details</span></button><button class="insight-preview" data-view="insights"><span class="tiny-label">THE MECHANICS</span><h3>Different ways to keep time.</h3><div class="preview-number">${a.calibers}<small> calibers</small></div><p>Automatic, manual and quartz movements bring variety beneath the surface.</p><span class="preview-link">Discover movement variety</span></button></div></section>
<section class="brand-ribbon"><p class="eyebrow">THE WATCHMAKERS</p><div>${DATA.insights.brands.map(b=>`<button data-browse-brand="${esc(b.name)}">${esc(b.name)}<small>${fmt(b.count)} references</small></button>`).join('')}</div></section>`;
}
let spotlightInterval=null;
function renderSpotlight(){
const r=featured()[state.spotlight%featured().length];
$('#spotlight-watch').innerHTML=`<button class="spotlight-product" data-record="${r.id}" aria-label="View ${esc(r.brand+' '+r.specific_model)}"><div class="spotlight-perspective"><div class="fallback" hidden><strong>${esc(r.brand)}</strong><small>${esc(r.reference_number)}</small></div><img src="${esc(safeUrl(r.image_url))}" alt="${esc(r.brand+' '+r.specific_model)}" referrerpolicy="no-referrer" onerror="this.parentElement.querySelector('.fallback').hidden=false;this.remove()"></div><div class="spotlight-caption"><span>${esc(r.brand)}</span><strong>${esc(r.specific_model)}</strong><small>${esc(r.diameter)} · ${esc(r.movement_family)}</small></div></button>`;
$('#stage-controls').innerHTML=featured().map((x,i)=>`<button data-spotlight="${i}" class="${i===state.spotlight?'selected':''}" aria-label="Feature ${esc(x.brand)}" aria-pressed="${i===state.spotlight}">${String(i+1).padStart(2,'0')}</button>`).join('');
document.querySelectorAll('[data-spotlight]').forEach(b=>b.onclick=()=>{state.spotlight=Number(b.dataset.spotlight);renderSpotlight()});
$('#watch-stage').classList.toggle('motion-paused',state.motionPaused);bindRecords();
}
function bindSpotlight(){
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)state.motionPaused=true;renderSpotlight();$('#motion-toggle').textContent=state.motionPaused?'Play animation':'Pause animation';$('#motion-toggle').setAttribute('aria-pressed',state.motionPaused);$('#motion-toggle').setAttribute('aria-label',(state.motionPaused?'Resume':'Pause')+' watch animation');
$('#motion-toggle').onclick=()=>{state.motionPaused=!state.motionPaused;$('#watch-stage').classList.toggle('motion-paused',state.motionPaused);$('#motion-toggle').textContent=state.motionPaused?'Play animation':'Pause animation';$('#motion-toggle').setAttribute('aria-pressed',state.motionPaused);$('#motion-toggle').setAttribute('aria-label',(state.motionPaused?'Resume':'Pause')+' watch animation')};
$('#watch-stage').addEventListener('pointermove',e=>{if(state.motionPaused||reduced)return;const b=e.currentTarget.getBoundingClientRect();e.currentTarget.style.setProperty('--tilt-x',((e.clientY-b.top)/b.height-.5)*-9+'deg');e.currentTarget.style.setProperty('--tilt-y',((e.clientX-b.left)/b.width-.5)*13+'deg')});
$('#watch-stage').addEventListener('pointerleave',e=>{e.currentTarget.style.setProperty('--tilt-x','0deg');e.currentTarget.style.setProperty('--tilt-y','0deg')});
spotlightInterval=setInterval(()=>{if(!state.motionPaused&&!document.hidden&&state.view==='overview'&&!$('#detail').open&&!$('#watch-stage').matches(':hover')&&!$('#watch-stage').contains(document.activeElement)){state.spotlight=(state.spotlight+1)%featured().length;renderSpotlight()}},7000);
}
function resetCatalog(){state.sort='curated';state.query='';state.brand='All brands';state.segment='All segments';state.movement='All movements';state.watchKind='All watch types';state.gems=false;state.page=1;render();}
function filteredRecords(){
let rows=DATA.records.filter(r=>r.is_watch&&(state.watchKind==='All watch types'||(r.watch_kind||'Wristwatch')===state.watchKind)&&(state.segment==='All segments'||r.segment===state.segment)&&(state.movement==='All movements'||r.movement_family===state.movement)&&(!state.gems||r.gem_set)&&(state.brand==='All brands'||r.brand===state.brand)&&(!state.query||[r.brand,r.reference_number,r.specific_model,r.parent_model,r.collection_label,r.case_material,r.caliber,r.dial_color].some(v=>(v||'').toLowerCase().includes(state.query.toLowerCase()))));
if(state.sort==='size')rows.sort((a,b)=>(b.diameter_mm??-1)-(a.diameter_mm??-1));
else if(state.sort==='model')rows.sort((a,b)=>a.specific_model.localeCompare(b.specific_model));
else if(state.sort==='coverage')rows.sort((a,b)=>b.coverage-a.coverage||a.specific_model.localeCompare(b.specific_model));
else rows=AtlasModel.curatedOrder(rows,DATA.brandOrder||[]);
return rows;
}
function catalog(){
return `${viewIntro('THE WATCH COLLECTION','A closer look at every reference.','Find a model by watchmaker, style, size or movement. Open a watch to explore its design and specifications.')}<div class="filters"><label class="search-wrap"><span aria-hidden="true">⌕</span><input id="catalog-search" type="search" aria-label="Search the watch catalog" placeholder="Search models, references, materials…" value="${esc(state.query)}"></label><label><span class="skip-label">Sort catalog</span><select id="catalog-sort" aria-label="Sort catalog"><option value="curated" ${state.sort==='curated'?'selected':''}>Curated order</option><option value="model" ${state.sort==='model'?'selected':''}>Model A–Z</option><option value="size" ${state.sort==='size'?'selected':''}>Largest case first</option></select></label></div><div class="chips" aria-label="Filter by watchmaker">${['All brands',...DATA.insights.brands.map(b=>b.name)].map(b=>`<button class="chip ${state.brand===b?'selected':''}" data-brand="${esc(b)}" aria-pressed="${state.brand===b}">${esc(b)} ${b!=='All brands'?`<span>(${fmt(DATA.insights.brands.find(x=>x.name===b).count)})</span>`:''}</button>`).join('')}</div><div class="catalog-secondary"><select id="catalog-kind" aria-label="Watch type">${['All watch types','Wristwatch','Pocket watch'].map(c=>`<option ${state.watchKind===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="catalog-segment" aria-label="Watch segment">${['All segments',...DATA.insights.categories].map(c=>`<option ${state.segment===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="catalog-movement" aria-label="Movement family">${['All movements','Automatic','Manual','Quartz','Not specified'].map(c=>`<option ${state.movement===c?'selected':''}>${esc(c)}</option>`).join('')}</select><button id="catalog-gems" class="gem-filter ${state.gems?'selected':''}" aria-pressed="${state.gems}">Gemstone details</button><button class="filter-reset" id="reset-catalog">Reset filters</button></div><div id="catalog-results" aria-live="polite"></div>`;
}
function renderCatalogResults(){
const rows=filteredRecords(),size=16,total=Math.max(1,Math.ceil(rows.length/size));state.page=Math.min(state.page,total);const start=(state.page-1)*size;
$('#catalog-results').innerHTML=`<div class="results-info"><span>${rows.length?`${fmt(start+1)}–${fmt(Math.min(start+size,rows.length))} of ${fmt(rows.length)} references`:'0 matching references'}</span><span>${esc(AtlasModel.snapshotLabel(rows))}</span></div>${rows.length?`<div class="catalog-grid">${rows.slice(start,start+size).map(watchCard).join('')}</div><div class="pagination"><button class="button" id="previous" ${state.page===1?'disabled':''}>Previous</button><span>Page ${state.page} of ${total}</span><button class="button" id="next" ${state.page===total?'disabled':''}>Next</button></div>`:'<div class="empty"><h2>No matching references</h2><p>Try another model, reference number or material.</p><button class="button" id="clear-filters">Clear filters</button></div>'}`;
$('#previous')?.addEventListener('click',()=>{state.page--;renderCatalogResults();$('#catalog-results').scrollIntoView({block:'start',behavior:'smooth'})});
$('#next')?.addEventListener('click',()=>{state.page++;renderCatalogResults();$('#catalog-results').scrollIntoView({block:'start',behavior:'smooth'})});
$('#clear-filters')?.addEventListener('click',()=>{resetCatalog()});bindRecords();
}
const processSteps=[
{title:'Understand the source before extracting it.',copy:'The notebooks begin with collection pages, product cards and the structures behind them. Each watchmaker needed a different path through its website.',points:['Map collection and product URLs for each watchmaker.','Inspect product-card selectors and specification sections.','Keep brand-specific discovery logic where page structures differ.'],file:'Universal Geneva.ipynb',code:'url = "https://universal.ch/nos-collections/homme/"\nsoup = BeautifulSoup(page_source, "html.parser")\nwatch_cards = soup.find_all("div", ...)',note:'A shortened excerpt of the archived collection-discovery code.'},
{title:'Start small. Define what useful looks like.',copy:'The Audemars Piguet notebook explicitly starts with a 15-watch pilot. The prepared tables then organize the results around reference numbers, models, prices, construction and movements.',points:['Pilot extraction on a bounded set of watch cards.','Use reference numbers and source URLs to identify records.','Prepare a shared schema while preserving fields specific to each source.'],file:'Audemars_Piguet_Project.ipynb',code:'# Notebook: “We will try our code first on 15 watches.”\nwatch_cards = soup.select(\'.ap-watch-card\')[0:15]\ndata = []',note:'The pilot and selector are documented in the project notebook.'},
{title:'Work with the page, including its dynamic parts.',copy:'Selenium drives the browser, while Beautiful Soup reads the rendered HTML. The Rolex notebook also uses explicit waits and a “view more” flow to expand the product listing.',points:['Render dynamic collection pages with Selenium.','Follow product links to extract detailed specifications.','Use explicit waits or delays before reading the page.'],file:'H_Moser_scrape_final.ipynb',code:'browser = webdriver.Chrome(options=options)\nbrowser.get(url)\ntime.sleep(5)\nsoup = BeautifulSoup(browser.page_source, "html.parser")',note:'A condensed example of the archived Selenium and Beautiful Soup approach; variable names are simplified.'},
{title:'Turn separate extracts into usable tables.',copy:'The archive contains review passes, renamed columns, table joins, enriched descriptions and image links. These iterations show the work between an initial scrape and a presentable dataset.',points:['Review and rename fields into the prepared schema.','Join tables and enrich records with images and descriptions.','Retain intermediate files and notebook checkpoints as evidence.'],file:'Audemars_after_review.ipynb',code:"df1.to_csv('audemars_piguet_reviewed.csv', index=False)",note:'The reviewed export is referenced in the archived notebook; the preserved Excel workbook provides the catalog’s Audemars Piguet data.'},
{title:'Make the work explorable—and traceable.',copy:'Watch Atlas presents the prepared datasets as a catalog, connects each reference to its source file, and separates available values from missing information. The archive tells the story behind the result.',points:['Coalesce repeated rows by brand and reference number.','Search by model, reference, material, caliber or dial.','Measure the presence of ten core fields and show data provenance.'],file:'Watch Atlas · Dashboard preparation',code:'Prepared tables → Reference normalization\n→ Field coverage → Searchable catalog\n→ Source provenance + project archive',note:'This dashboard layer was created from the preserved archive. It does not re-run the scrapers or change the original files.'}
];
function method(){return `${viewIntro('FROM RESEARCH TO RESULT','The work behind the collection.','A practical workflow evidenced by the notebooks, prepared exports, review passes and checkpoints in this project.')}<div class="method-layout"><div class="method-nav" role="tablist" aria-label="Project stages">${stepNames.map((n,i)=>`<button class="method-button ${state.method===i?'active':''}" id="stage-${i}" role="tab" aria-selected="${state.method===i}" aria-controls="method-panel" data-stage="${i}"><small>STAGE 0${i+1}</small>${n}</button>`).join('')}</div><div class="panel method-content" id="method-panel" role="tabpanel" aria-labelledby="stage-${state.method}"></div></div><div class="quality-note">The workflow describes what is evidenced in the preserved project. Exploratory notebooks do not establish complete coverage of a watchmaker’s website.</div>`;}
function renderMethod(){const s=processSteps[state.method];$('#method-panel').innerHTML=`<p class="eyebrow">0${state.method+1} / ${stepNames[state.method].toUpperCase()}</p><h2>${s.title}</h2><p>${s.copy}</p><ul>${s.points.map(p=>`<li>${p}</li>`).join('')}</ul><div class="evidence"><h3>Explore the work behind this stage</h3><p>The project archive brings together the source material, working notebooks and reviewed exports.</p><button class="button quiet" data-view="archive">Open project archive</button></div>`;bindRecords();}
function quality(){const brands=DATA.insights.brands.map(b=>({...b,records:b.count,fields:Object.fromEntries(DATA.coreFields.map(k=>[k,DATA.records.filter(r=>r.is_watch&&r.brand===b.name&&r[k]).length]))})),s=DATA.stats,coverage=Math.round(brands.reduce((n,b)=>n+Object.values(b.fields).reduce((a,v)=>a+v,0),0)/(DATA.insights.overall.count*DATA.coreFields.length)*100);
return `${viewIntro('THE COLLECTION AT A GLANCE','Know what is available.','See which specifications are documented for each watchmaker, and where the collection has gaps.')}<div class="metrics"><div class="metric"><span class="metric-title">Specifications available</span><span class="metric-value">${coverage}%</span><span class="metric-note">Across ten common specifications</span></div><div class="metric"><span class="metric-title">Measured case diameters</span><span class="metric-value">${fmt(DATA.insights.overall.diameterN)}</span><span class="metric-note">Wristwatch diameters used in comparisons</span></div><div class="metric"><span class="metric-title">Watches with named calibers</span><span class="metric-value">${fmt(DATA.insights.overall.caliberN)}</span><span class="metric-note">Watches with a named caliber</span></div><div class="metric"><span class="metric-title">Collections represented</span><span class="metric-value">${s.families}</span><span class="metric-note">Across ${DATA.insights.brands.length} watchmakers</span></div></div><section class="panel"><h2>Specification availability</h2><p class="muted" style="font-size:14px;margin:8px 0">The share of collection entries with each specification recorded. Empty specifications remain unspecified.</p><div class="table-wrap"><table class="quality-table"><thead><tr><th scope="col">Field</th>${brands.map(b=>`<th scope="col">${esc(b.name)}</th>`).join('')}</tr></thead><tbody>${DATA.coreFields.map(k=>`<tr><th scope="row">${friendly(k)}</th>${brands.map(b=>{const p=Math.round(b.fields[k]/b.records*100);return `<td><span class="field-cell" style="background:rgba(144,192,130,${.05+p/650})">${p}% <span class="muted">(${fmt(b.fields[k])}/${fmt(b.records)})</span></span></td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="quality-note">Availability measures whether a value was recorded, rather than whether it has been independently verified. The collection combines the 2023–2024 archive with October 2026 official catalogs; prices and availability may have changed.</div></section><div class="insights-grid" style="margin-top:24px"><section class="panel"><h2>Watchmakers in the collection</h2><div class="table-wrap"><table class="quality-table"><thead><tr><th>Watchmaker</th><th>Catalog references</th><th>Available material</th></tr></thead><tbody>${brands.map(b=>`<tr><th scope="row">${esc(b.name)}</th><td>${fmt(b.records)}</td><td><span class="status-tag">Watch specifications</span></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Most represented collections</h2><p class="muted" style="font-size:13px;margin-top:8px">The largest collections in the captured catalog</p>${DATA.collections.map(c=>`<div class="coverage-row"><div><span>${esc(c.name)}</span><span class="count">${fmt(c.count)}</span></div><div class="bar"><span style="width:${c.count/DATA.collections[0].count*100}%"></span></div></div>`).join('')}</section></div><section class="panel" style="margin-top:24px"><h2>Collection datasets</h2><div class="table-wrap"><table class="quality-table source-table"><thead><tr><th>Watchmaker / dataset</th><th>Rows captured</th></tr></thead><tbody>${DATA.sources.map(x=>`<tr><td>${esc(x.brand)} · ${x.id?esc('Official catalog · '+(x.captured_date_range||x.captured_date)):x.file.includes('reviewed')?'Reviewed specifications':x.file.includes('variations')?'Watch variations':x.file.includes('mod_done')?'Prepared specifications':'Collection specifications'}</td><td>${fmt(x.rows)}</td></tr>`).join('')}</tbody></table></div><p class="muted" style="font-size:13px;margin:18px 0 0">The project archive contains the original datasets and preparation history.</p></section>`;
}
const formatBytes=b=>b>=1048576?(b/1048576).toFixed(1)+' MB':b>=1024?Math.round(b/1024)+' KB':b+' B';
function archive(){const count=c=>DATA.inventory.filter(x=>x.category===c).length;
return `${viewIntro('THE PROJECT WORKBENCH','Every file has a place.','An organized index of all 73 preserved files: the working notebooks, prepared data, spreadsheets and iterations behind this project.')}<div class="metrics archive-metrics" aria-label="Project archive metrics"><div class="metric"><span class="metric-title">Research notebooks</span><span class="metric-value">${DATA.stats.notebooks}</span><span class="metric-note">Working research and scraping sessions</span></div><div class="metric"><span class="metric-title">Preserved project files</span><span class="metric-value">${DATA.stats.files}</span><span class="metric-note">The complete recovered archive</span></div><div class="metric"><span class="metric-title">Notebook checkpoints</span><span class="metric-value">${DATA.stats.checkpoints}</span><span class="metric-note">Saved iterations of the work</span></div><div class="metric"><span class="metric-title">Prepared source rows</span><span class="metric-value">${fmt((DATA.archiveStats||DATA.stats).sourceRows)}</span><span class="metric-note">Before reference-level organization</span></div></div><div class="archive-summary">${['Dataset','Spreadsheet','Notebook','Checkpoint','Document','Text export'].map(c=>`<span class="archive-stat"><b>${count(c)}</b>${c}${count(c)===1?'':'s'}</span>`).join('')}</div><div class="filters"><label class="search-wrap"><span aria-hidden="true">⌕</span><input type="search" id="archive-search" aria-label="Search project files" placeholder="Search a filename, watchmaker or technique…" value="${esc(state.archiveQuery)}"></label><select id="archive-type" aria-label="Filter file type">${['All files','Dataset','Spreadsheet','Notebook','Checkpoint','Document','Text export'].map(c=>`<option ${c===state.archiveType?'selected':''}>${c}</option>`).join('')}</select></div><div id="archive-results" aria-live="polite"></div><div class="quality-note">This dashboard indexes the archive and presents selected prepared data. Raw notebooks and document contents remain in the preserved local folder; the original files are unchanged.</div><section class="panel" style="margin-top:24px"><h2>Breguet collection-discovery index</h2><p class="muted" style="font-size:14px;margin:8px 0 0">Nine collection-level links from the preliminary export. These are discovery entries, not individual watch references.</p><div class="index-grid">${DATA.collectionIndex.map(r=>`<a class="index-card" href="${esc(safeUrl(r.watch_URL))}" target="_blank" rel="noopener noreferrer">${esc(r.watch_name)}<small>Historical watchmaker link</small></a>`).join('')}</div></section>`;
}
function renderArchive(){const q=state.archiveQuery.toLowerCase();const items=DATA.inventory.filter(x=>(state.archiveType==='All files'||x.category===state.archiveType)&&(!q||[x.name,x.brand,x.path,...x.techniques||[]].some(s=>s.toLowerCase().includes(q))));$('#archive-results').innerHTML=`<div class="results-info"><span>${items.length} of ${DATA.inventory.length} files</span><span>Inventory only · originals preserved</span></div>${items.length?`<div class="table-wrap"><table class="quality-table archive-table"><thead><tr><th scope="col">File / location</th><th scope="col">Watchmaker</th><th scope="col">Type</th><th scope="col">Modified</th><th scope="col">Size</th></tr></thead><tbody>${items.map(x=>`<tr><td class="file-name"><strong>${esc(x.name)}</strong><small>${esc(x.path)}</small>${x.techniques?.length?`<div>${x.techniques.map(t=>`<span class="tech-tag">${esc(t)}</span>`).join('')}</div>`:''}</td><td>${esc(x.brand)}</td><td>${esc(x.category)}</td><td>${esc(x.date)}</td><td>${formatBytes(x.bytes)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>No matching files</h2><p>Try a watchmaker, filename or technique.</p></div>'}`;}
function render(){
clearInterval(spotlightInterval);const views={overview,catalog,method,quality,archive,insights};$('#main').innerHTML=(views[state.view]||overview)();
$('#current-view').textContent={overview:'OVERVIEW',catalog:'WATCH CATALOG',method:'THE PROCESS',quality:'DATA COVERAGE',archive:'PROJECT ARCHIVE',insights:'COLLECTION INSIGHTS'}[state.view];
document.querySelectorAll('.nav-button').forEach(b=>{const current=b.dataset.view===state.view;b.classList.toggle('active',current);b.setAttribute('aria-current',current?'page':'false')});
if(state.view==='overview'){bindSpotlight();}else if(state.view==='insights'){bindInsights();}else if(state.view==='catalog'){
renderCatalogResults();$('#catalog-kind').addEventListener('change',e=>{state.watchKind=e.target.value;state.page=1;renderCatalogResults()});$('#catalog-segment').addEventListener('change',e=>{state.segment=e.target.value;state.page=1;renderCatalogResults()});$('#catalog-movement').addEventListener('change',e=>{state.movement=e.target.value;state.page=1;renderCatalogResults()});$('#catalog-gems').onclick=()=>{state.gems=!state.gems;state.page=1;$('#catalog-gems').classList.toggle('selected',state.gems);$('#catalog-gems').setAttribute('aria-pressed',state.gems);renderCatalogResults()};$('#reset-catalog').onclick=resetCatalog;$('#catalog-search').addEventListener('input',e=>{state.query=e.target.value;state.page=1;renderCatalogResults()});$('#catalog-sort').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;renderCatalogResults()});document.querySelectorAll('[data-brand]').forEach(b=>b.onclick=()=>{state.brand=b.dataset.brand;state.page=1;render()});
}else if(state.view==='method'){
renderMethod();document.querySelectorAll('[data-stage]').forEach(b=>{b.onclick=()=>{state.method=Number(b.dataset.stage);document.querySelectorAll('[data-stage]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b)});$('#method-panel').setAttribute('aria-labelledby',b.id);renderMethod()};b.onkeydown=e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const target=e.key==='Home'?0:e.key==='End'?4:(state.method+(e.key==='ArrowDown'||e.key==='ArrowRight'?1:4))%5;document.querySelector(`[data-stage="${target}"]`).click();document.querySelector(`[data-stage="${target}"]`).focus()}}});
}else if(state.view==='archive'){
renderArchive();$('#archive-search').addEventListener('input',e=>{state.archiveQuery=e.target.value;renderArchive()});$('#archive-type').addEventListener('change',e=>{state.archiveType=e.target.value;renderArchive()});
}bindRecords();
}
function bindRecords(){document.querySelectorAll('[data-browse-brand]').forEach(b=>b.onclick=()=>{state.brand=b.dataset.browseBrand;state.query='';state.segment='All segments';state.movement='All movements';state.watchKind='All watch types';state.gems=false;state.page=1;navigate('catalog')});document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>openRecord(b.dataset.record));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));}
function bindInsights(){ $('#insight-brand').addEventListener('change',e=>{state.insightBrand=e.target.value;render()});document.querySelectorAll('[data-explore-brand]').forEach(b=>b.onclick=()=>{state.brand=b.dataset.exploreBrand==='All watchmakers'?'All brands':b.dataset.exploreBrand;state.segment=b.dataset.exploreSegment||'All segments';state.gems=b.dataset.exploreGems==='true';state.query=b.dataset.exploreCollection||'';state.movement='All movements';state.watchKind='All watch types';state.page=1;navigate('catalog')});}
function navigate(view){if(!['overview','catalog','method','quality','archive','insights'].includes(view))return;state.view=view;history.replaceState(null,'','#'+view);render();window.scrollTo({top:0});}
function openRecord(id){
const r=DATA.records.find(x=>x.id===id);if(!r)return;
const fields=AtlasModel.columns.filter(k=>!['brand','reference_number','watch_URL','short_description','description','currency','price','parent_model','specific_model'].includes(k));
const extras=[...(r.extra_specs||[]),...(r.diameter_note?[{label:'Case measurement details',value:r.diameter_note}]:[])];
$('#detail-content').innerHTML=`<div class="detail-top">${visual(r)}<div class="detail-heading"><p class="eyebrow">${esc(r.brand)}</p><h2 id="detail-title">${esc(r.specific_model)}</h2><p>${esc(r.reference_number)} · ${esc(r.watch_kind||'Wristwatch')}</p><p class="price">${esc(price(r))}</p>${r.price_tax_label?`<p>${esc(r.price_tax_label)}</p>`:''}<p>Recorded ${esc(r.captured_label||'in 2023–2024')}${r.market?' · '+esc(r.market):''}. Prices and availability may have changed.</p>${safeUrl(r.watch_URL)?`<a class="button" href="${esc(safeUrl(r.watch_URL))}" target="_blank" rel="noopener noreferrer">Watchmaker source</a>`:''}</div></div><div class="detail-bottom"><div class="spec-grid">${fields.map(k=>`<div class="spec"><small>${friendly(k)}</small>${esc(k==='diameter'?(r.diameter_mm!==null?r.diameter_mm+' mm':r[k]||'Not specified'):r[k]||'Not specified')}</div>`).join('')}${extras.map(x=>`<div class="spec"><small>${esc(x.label)}</small>${esc(x.value)}</div>`).join('')}</div>${r.description||r.short_description?`<p class="description">${esc(r.description||r.short_description)}</p>`:''}<div class="source-list"><details><summary>Source details</summary><p>${r.sources.map(x=>esc(x.split('/').pop())).join('<br>')}</p><p>${esc(r.segment)} · ${r.gem_set?'Decorative gemstone details recorded':'Gemstone details unconfirmed'}</p></details></div></div>`;
$('#detail').showModal();
}
$('.close').onclick=()=>$('#detail').close();
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});
function registerCatalogTool(){
if(!document.modelContext?.registerTool)return;
try{Promise.resolve(document.modelContext.registerTool({name:'search_watch_catalog',title:'Search the watch catalog',description:'Search collected watch references and apply the same brand and text filters as the visible catalog.',inputSchema:{type:'object',properties:{query:{type:'string'},brand:{type:'string',enum:['All brands',...DATA.brands.filter(b=>b.records).map(b=>b.name)]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>!['query','brand'].includes(k))||input.query!==undefined&&typeof input.query!=='string'||input.brand!==undefined&&!['All brands',...DATA.brands.filter(b=>b.records).map(b=>b.name)].includes(input.brand))throw new Error('Provide a text query and a supported watchmaker.');state.query=input.query||'';state.brand=input.brand||'All brands';state.segment='All segments';state.movement='All movements';state.watchKind='All watch types';state.gems=false;state.page=1;navigate('catalog');const rows=filteredRecords();return{matches:rows.length,visibleView:state.view,records:rows.slice(0,8).map(r=>({brand:r.brand,reference:r.reference_number,model:r.specific_model}))}}})).catch(()=>{});}catch{}
}
fetch('data.json').then(r=>{if(!r.ok)throw new Error();return r.json()}).then(data=>{DATA=data;$('#nav-count').textContent=fmt(DATA.insights.overall.count);state.view=['overview','catalog','method','quality','archive','insights'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';render();registerCatalogTool()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h1>The collection could not load.</h1><p>Please reload the page to try again.</p></div>'});
